import zipfile, os

os.makedirs('verify_contents', exist_ok=True)
with zipfile.ZipFile('/root/event_announcement_ready.hwpx', 'r') as z:
    z.extractall('verify_contents')

# Check no placeholders remain
for root, dirs, files in os.walk('verify_contents'):
    for f in files:
        path = os.path.join(root, f)
        with open(path, 'r', encoding='utf-8') as fh:
            content = fh.read()
            if '{{' in content:
                print('WARNING: remaining placeholders in', path)
                print(content[:500])

# Verify Korean labels are preserved
for root, dirs, files in os.walk('verify_contents'):
    for f in files:
        path = os.path.join(root, f)
        with open(path, 'r', encoding='utf-8') as fh:
            content = fh.read()
            for label in ['행사명:', '일시:', '장소:', '주관:', '대상:', '참가비:', '신청 마감:', '문의:', '상세 내용:', '주의사항:', '비고: 사전 신청 필수']:
                if label in content:
                    print('Found label:', label)

# Verify JSON values appear in output
for root, dirs, files in os.walk('verify_contents'):
    for f in files:
        path = os.path.join(root, f)
        with open(path, 'r', encoding='utf-8') as fh:
            content = fh.read()
            for val in ['2026년 하반기 전사 워크숍', '경기도 성남시 분당구 대왕판교로 660 그랜드볼룸', '인재개발팀', '무료 (회사 지원)']:
                if val in content:
                    print('Found value:', val)

# Check layout cache elements are removed
for root, dirs, files in os.walk('verify_contents'):
    for f in files:
        path = os.path.join(root, f)
        with open(path, 'r', encoding='utf-8') as fh:
            content = fh.read()
            if 'linesegarray' in content.lower():
                print('WARNING: layout cache still present in', path)
            else:
                print('OK: no linesegarray in', path)
